public class ParquetMetadataConverterFromParquetMetadataTests {

  @Test
  public void testFromParquetMetadataWithNullParquetMetadata() {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();

    assertThatThrownBy(() -> converter.fromParquetMetadata(null, null, false, new HashMap<>()))
        .isInstanceOf(NullPointerException.class);
  }

  @Test
  public void testFromParquetMetadataWithNullRowGroupToRowIndexOffsetMap() {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();

    FileMetaData fileMetaData = mock(FileMetaData.class);

    assertThatThrownBy(() -> converter.fromParquetMetadata(fileMetaData, null, false, null))
        .isInstanceOf(NullPointerException.class);
  }

  @Test
  public void testFromParquetMetadataWithEmptyRowGroups() throws IOException {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();

    FileMetaData fileMetaData = mock(FileMetaData.class);
    when(fileMetaData.getRow_groups()).thenReturn(null);

    MessageType schema = parseMessageType("message test { optional int32 a; }");
    when(fileMetaData.getSchema()).thenReturn(createSchemaElements());
    when(fileMetaData.getColumn_orders()).thenReturn(null);

    ParquetMetadata result = converter.fromParquetMetadata(fileMetaData, null, false, new HashMap<>());

    assertThat(result).isNotNull();
    assertThat(result.getBlocks()).isEmpty();
  }

  @Test
  public void testFromParquetMetadataWithSingleRowGroup() throws IOException {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();

    // Create mock data
    FileMetaData fileMetaData = mock(FileMetaData.class);
    when(fileMetaData.getRow_groups()).thenReturn(createMockRowGroups());
    when(fileMetaData.getSchema()).thenReturn(createSchemaElements());
    when(fileMetaData.getColumn_orders()).thenReturn(createColumnOrders());

    ParquetMetadata result = converter.fromParquetMetadata(fileMetaData, null, false, new HashMap<>());

    assertThat(result).isNotNull();
    assertThat(result.getBlocks()).hasSize(1);

    BlockMetaData block = result.getBlocks().get(0);
    assertThat(block.getRowCount()).isEqualTo(100);
    assertThat(block.getTotalByteSize()).isEqualTo(1024);
  }

  @Test
  public void testFromParquetMetadataWithMultipleRowGroups() throws IOException {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();

    // Create mock data with multiple row groups
    FileMetaData fileMetaData = mock(FileMetaData.class);
    when(fileMetaData.getRow_groups()).thenReturn(createMultipleMockRowGroups());
    when(fileMetaData.getSchema()).thenReturn(createSchemaElements());
    when(fileMetaData.getColumn_orders()).thenReturn(createColumnOrders());

    ParquetMetadata result = converter.fromParquetMetadata(fileMetaData, null, false, new HashMap<>());

    assertThat(result).isNotNull();
    assertThat(result.getBlocks()).hasSize(2);

    BlockMetaData firstBlock = result.getBlocks().get(0);
    assertThat(firstBlock.getRowCount()).isEqualTo(100);
    assertThat(firstBlock.getTotalByteSize()).isEqualTo(1024);

    BlockMetaData secondBlock = result.getBlocks().get(1);
    assertThat(secondBlock.getRowCount()).isEqualTo(200);
    assertThat(secondBlock.getTotalByteSize()).isEqualTo(2048);
  }

  @Test
  public void testFromParquetMetadataWithPlaintextColumns() throws IOException {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();

    FileMetaData fileMetaData = mock(FileMetaData.class);
    when(fileMetaData.getRow_groups()).thenReturn(createMockRowGroups());
    when(fileMetaData.getSchema()).thenReturn(createSchemaElements());
    when(fileMetaData.getColumn_orders()).thenReturn(createColumnOrders());

    ParquetMetadata result = converter.fromParquetMetadata(fileMetaData, null, false, new HashMap<>());

    assertThat(result).isNotNull();
    assertThat(result.getBlocks()).hasSize(1);

    BlockMetaData block = result.getBlocks().get(0);
    assertThat(block.getColumns()).hasSize(1);

    ColumnChunkMetaData column = block.getColumns().get(0);
    assertThat(column.getPath().toString()).isEqualTo("a");
  }

  @Test
  public void testFromParquetMetadataWithColumnIndexAndOffsetIndex() throws IOException {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();

    FileMetaData fileMetaData = mock(FileMetaData.class);
    when(fileMetaData.getRow_groups()).thenReturn(createMockRowGroups());
    when(fileMetaData.getSchema()).thenReturn(createSchemaElements());
    when(fileMetaData.getColumn_orders()).thenReturn(createColumnOrders());

    Map<RowGroup, Long> rowIndexOffsetMap = new HashMap<>();
    RowGroup rowGroup = createMockRowGroup();
    rowIndexOffsetMap.put(rowGroup, 1000L);

    ParquetMetadata result = converter.fromParquetMetadata(fileMetaData, null, false, rowIndexOffsetMap);

    assertThat(result).isNotNull();
    assertThat(result.getBlocks()).hasSize(1);

    BlockMetaData block = result.getBlocks().get(0);
    assertThat(block.getRowIndexOffset()).isEqualTo(1000L);
  }

  @Test
  public void testFromParquetMetadataWithInvalidFilePathsInSameRowGroup() {
    ParquetMetadataConverter converter = new ParquetMetadataConverter();

    FileMetaData fileMetaData = mock(FileMetaData.class);
    when(fileMetaData.getRow_groups()).thenReturn(createRowGroupWithDifferentFilePaths());
    when(fileMetaData.getSchema()).thenReturn(createSchemaElements());
    when(fileMetaData.getColumn_orders()).thenReturn(createColumnOrders());

    assertThatThrownBy(() -> converter.fromParquetMetadata(fileMetaData, null, false, new HashMap<>()))
        .isInstanceOf(ParquetDecodingException.class)
        .hasMessageContaining("all column chunks of the same row group must be in the same file");
  }

  private List<RowGroup> createMockRowGroups() {
    List<RowGroup> rowGroups = new ArrayList<>();
    rowGroups.add(createMockRowGroup());
    return rowGroups;
  }

  private List<RowGroup> createMultipleMockRowGroups() {
    List<RowGroup> rowGroups = new ArrayList<>();
    rowGroups.add(createMockRowGroup());
    rowGroups.add(createMockRowGroup2());
    return rowGroups;
  }

  private RowGroup createMockRowGroup() {
    RowGroup rowGroup = new RowGroup();
    rowGroup.setNum_rows(100);
    rowGroup.setTotal_byte_size(1024);
    rowGroup.setColumns(createMockColumnChunks());
    return rowGroup;
  }

  private RowGroup createMockRowGroup2() {
    RowGroup rowGroup = new RowGroup();
    rowGroup.setNum_rows(200);
    rowGroup.setTotal_byte_size(2048);
    rowGroup.setColumns(createMockColumnChunks());
    return rowGroup;
  }

  private List<ColumnChunk> createMockColumnChunks() {
    List<ColumnChunk> columnChunks = new ArrayList<>();
    ColumnChunk columnChunk = new ColumnChunk();
    columnChunk.setFile_path("/test/file.parquet");
    columnChunk.setMeta_data(createMockColumnMetaData());
    columnChunks.add(columnChunk);
    return columnChunks;
  }

  private ColumnMetaData createMockColumnMetaData() {
    ColumnMetaData metaData = new ColumnMetaData();
    metaData.setType(INT32);
    metaData.setEncodings(java.util.Arrays.asList(Encoding.PLAIN));
    metaData.setPath_in_schema(java.util.Arrays.asList("a"));
    metaData.setNum_values(100);
    metaData.setTotal_compressed_size(512);
    metaData.setTotal_uncompressed_size(1024);
    return metaData;
  }

  private List<SchemaElement> createSchemaElements() {
    List<SchemaElement> schemaElements = new ArrayList<>();
    SchemaElement element = new SchemaElement();
    element.setName("test");
    element.setRepetition_type(org.apache.parquet.format.RepetitionType.REQUIRED);
    element.setType(Type.RECORD);
    schemaElements.add(element);

    SchemaElement field = new SchemaElement();
    field.setName("a");
    field.setRepetition_type(org.apache.parquet.format.RepetitionType.OPTIONAL);
    field.setType(INT32);
    field.setConverted_type(ConvertedType.INT_32);
    schemaElements.add(field);

    return schemaElements;
  }

  private List<ColumnOrder> createColumnOrders() {
    List<ColumnOrder> columnOrders = new ArrayList<>();
    ColumnOrder columnOrder = new ColumnOrder();
    columnOrder.setType(Type.SORTED);
    columnOrders.add(columnOrder);
    return columnOrders;
  }

  private List<RowGroup> createRowGroupWithDifferentFilePaths() {
    List<RowGroup> rowGroups = new ArrayList<>();
    RowGroup rowGroup = new RowGroup();
    rowGroup.setNum_rows(100);
    rowGroup.setTotal_byte_size(1024);

    List<ColumnChunk> columnChunks = new ArrayList<>();

    ColumnChunk chunk1 = new ColumnChunk();
    chunk1.setFile_path("/test/file1.parquet");
    chunk1.setMeta_data(createMockColumnMetaData());
    columnChunks.add(chunk1);

    ColumnChunk chunk2 = new ColumnChunk();
    chunk2.setFile_path("/test/file2.parquet"); // Different file path
    chunk2.setMeta_data(createMockColumnMetaData());
    columnChunks.add(chunk2);

    rowGroup.setColumns(columnChunks);
    rowGroups.add(rowGroup);
    return rowGroups;
  }
}
